css:
/* ===== 全局：暖纸画布、去阴影、去渐变、去毛玻璃、hover 位移清零 ===== */
.aurora { display: none; }
* { backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
.stat, .kcard { transform: none !important; }
.stat .num, .stat .label, .kcard .ctitle, .kcard .cmeta, .kcard .csummary, .kcard .ctags { transform: none !important; }
.reveal { opacity: 1 !important; transform: none !important; transition: none !important; }
.neb-tag, #landing .mark, #modal { animation: none !important; }
.btn:hover, .chip:hover, .tl-item:hover { transform: none !important; }
.btn, .chip, nav button, .kcard, .stat, .panel, .plan-card, .tl-item, #theme-switch, .search-box { transition: color .2s ease, background .2s ease, border-color .2s ease !important; }
::selection { background: #e6f3fe; }

/* ===== 版式骨架：Notion 式窄栏文档单栏（860px 居中纸面） ===== */
main { max-width: 860px; padding: 0 24px 96px; }
.dash-grid { grid-template-columns: 1fr; gap: 16px; }
.insight-grid { grid-template-columns: 1fr; gap: 16px; }
#graph-box { height: 560px; min-height: 420px; }

/* ===== 正文排版：Inter 400 正文 / 600-700 负字距标题 ===== */
body { font-size: 16px; line-height: 1.6; }
.brand h1 { font-family: var(--font-display); font-weight: 700; letter-spacing: -0.02em; font-size: 19px; }
.brand h1 em { color: var(--accent); }
.brand .sub { letter-spacing: .04em; font-size: 11px; color: var(--text-faint); }

/* ===== 顶栏 64px，内容与文档栏对齐；滚动时补不透明暖纸底 ===== */
header {
  height: 64px; background: var(--bg); border-bottom: 1px solid transparent;
  padding-left: max(24px, calc(50% - 430px)); padding-right: max(24px, calc(50% - 430px));
}
header.scrolled { border-bottom-color: transparent; background: var(--bg); box-shadow: 0 .7px 1.462px rgba(0,0,0,.015), 0 3px 9px rgba(0,0,0,.03); }
nav { background: transparent; border: 0; padding: 0; gap: 2px; border-radius: 0; }
nav button { border-radius: 8px; padding: 12px 16px; font-size: 14px; font-weight: 500; letter-spacing: 0; color: rgba(0,0,0,.54); }
nav button:hover { color: #000; background: rgba(0,0,0,.04); }
nav button.active { background: rgba(0,0,0,.05); color: #000; }
#theme-switch { border-radius: 8px; border: 1px solid rgba(0,0,0,.14); background: transparent; color: rgba(0,0,0,.54); font-size: 13px; padding: 8px 12px; }
#theme-switch:hover { color: #000; border-color: rgba(0,0,0,.3); }
#btn-import { border-radius: 8px; border-color: rgba(0,0,0,.14); color: rgba(0,0,0,.54); padding: 8px 12px; font-size: 13px; }
#btn-import:hover { border-color: #0075de; color: #0075de; }

/* ===== Hero：文档文首——左对齐标题栈 + 居中的 network 签名插图（白卡细线画框） ===== */
.hero { grid-template-columns: 1fr; text-align: left; justify-items: stretch; padding: 40px 0 36px; min-height: 0; gap: 0; }
.nebula { display: none; }
.hero .sig {
  display: block; width: min(400px, 100%); height: 230px; margin: 0 auto 36px;
  background: #fff; border: 1px solid rgba(0,0,0,.08); border-radius: 12px; overflow: hidden;
}
.hello {
  letter-spacing: 0; text-transform: none; font-size: 12px; font-weight: 500;
  color: #0075de; background: #e6f3fe; border-radius: 9999px; padding: 4px 12px;
  margin-bottom: 24px; display: inline-flex;
}
.hello::before { display: none; }
.hero-title {
  font-weight: 700; font-size: clamp(30px, 3.6vw, 42px); line-height: 1.15;
  letter-spacing: -0.028em; color: #111; margin-bottom: 20px; max-width: 24ch;
}
.hero-title.long { font-size: clamp(24px, 2.8vw, 34px); line-height: 1.3; letter-spacing: -0.02em; font-weight: 700; max-width: 28ch; }
.hero-title .hl {
  background: #f6d5b8; color: #111; -webkit-background-clip: initial; background-clip: initial;
  border-radius: 9999px; padding: .02em .3em; white-space: nowrap;
}
.hero-essence {
  font-family: "Source Serif 4", "Noto Serif SC", "Songti SC", serif; font-style: italic;
  font-size: 18px; line-height: 1.56; color: #615d59; max-width: 56ch; margin: 0 0 28px;
}
.hero-essence strong { color: #111; font-weight: 600; font-style: normal; }
.hero-actions { justify-content: flex-start; }

/* ===== 趋势条：Pill Tag 化的数据摘要（白底发线 pill） ===== */
.trend-row { justify-content: flex-start; margin: -4px 0 28px; }
.trend {
  background: #fff; border: 1px solid rgba(0,0,0,.08); border-radius: 9999px;
  padding: 4px 12px; font-size: 12px; letter-spacing: 0; color: #615d59;
}
.trend b { color: #0075de; font-weight: 600; }

/* ===== 按钮三档：Primary CTA / Ghost CTA（天蓝）/ Outlined Text（1px 墨线 4px 圆角） ===== */
.btn { border-radius: 8px; padding: 8px 16px; font-size: 14px; font-weight: 500;
  background: transparent; border: 1px solid rgba(0,0,0,.24); color: rgba(0,0,0,.9); }
.btn:hover { background: rgba(0,0,0,.04); border-color: rgba(0,0,0,.24); }
.btn.primary { background: #0075de; border-color: #0075de; color: #fff; }
.btn.primary:hover { filter: brightness(1.06); box-shadow: none; background: #0075de; }
.btn.ghost { background: #e6f3fe; border-color: transparent; color: #0075de; }
.btn.ghost:hover { background: #d8ecfd; border-color: transparent; }
#status-bar .btn.ghost, .modal-actions .btn.ghost {
  background: transparent; border: 1px solid rgba(0,0,0,.3); color: rgba(0,0,0,.9);
  border-radius: 4px; padding: 5px 10px;
}
#status-bar .btn.ghost:hover, .modal-actions .btn.ghost:hover { background: rgba(0,0,0,.04); }

/* ===== 落地页标记：白底细线方块 ===== */
#landing .mark {
  width: 72px; height: 72px; border-radius: 8px; background: #fff;
  border: 1px solid rgba(0,0,0,.08); box-shadow: none; color: #0075de;
  font-family: var(--font-display); font-weight: 700; font-size: 34px;
}
#landing h2 { font-weight: 700; letter-spacing: -0.02em; font-size: 28px; color: #111; }
#landing p { font-size: 15px; color: #615d59; }

/* ===== White Feature Card 基准：白面 + 1px 发线、零阴影、克制圆角 ===== */
.stat, .panel, .kcard, .plan-card, .tl-item, #graph-box, #modal {
  background: #fff; border: 1px solid rgba(0,0,0,.08); box-shadow: none;
}
.stat, .panel, .kcard, .plan-card, #graph-box, .tl-item { border-radius: 8px; }
.stat:hover, .panel:hover, .kcard:hover, .plan-card:hover, .tl-item:hover { border-color: rgba(0,0,0,.2); }
.dash-grid { gap: 16px; }
.panel { padding: 24px; }
.panel h3 { font-size: 16px; font-weight: 600; letter-spacing: -0.011em; color: #111; margin-bottom: 16px; }
.panel h3::after { background: rgba(0,0,0,.08); }

/* ===== stat-row：文档内四栏小卡片（紧凑数字注脚） ===== */
.stat-row { gap: 12px; margin-bottom: 16px; }
.stat { padding: 16px 18px; }
.stat .num { font-size: 26px; font-weight: 700; letter-spacing: -0.02em; color: #111; }
.stat .label { font-size: 12px; letter-spacing: .01em; color: #757575; margin-top: 6px; }
.stat .spark { display: none; }

/* ===== 知识卡片：纵向列表式宽卡（白面发线，hover 出蓝色发线） ===== */
#cards-grid { grid-template-columns: 1fr !important; gap: 12px !important; perspective: none !important; }
.kcard { padding: 20px 24px; gap: 10px; }
.kcard:hover { border-color: rgba(0,117,222,.4); }
.kcard .ctitle { font-size: 17px; font-weight: 700; letter-spacing: -0.011em; line-height: 1.45; color: #111; }
.kcard .cmeta { color: #757575; }
.kcard .csummary { font-size: 14px; color: #615d59; line-height: 1.6; -webkit-line-clamp: 2; }

/* ===== Pill Tag 规范：9999px 全圆角、4px 12px 内边距、彩色平涂 ===== */
.mini-tag { background: #e6f3fe; color: #0075de; letter-spacing: 0; font-weight: 500; font-size: 12px; padding: 4px 12px; border-radius: 9999px; }
.chip { border-radius: 9999px; background: transparent; border: 1px solid rgba(0,0,0,.14); color: rgba(0,0,0,.6); padding: 8px 16px; letter-spacing: 0; }
.chip:hover { color: #000; border-color: rgba(0,0,0,.3); background: rgba(0,0,0,.03); }
.chip.active { background: #0075de; border-color: #0075de; color: #fff; }
.status-badge { border-radius: 9999px; border: 0; background: #efedeb; color: #615d59; letter-spacing: 0; font-weight: 500; padding: 4px 12px; }
.status-badge.active { background: #e6f3fe; color: #0075de; }

/* ===== 搜索框：白底方角描边 ===== */
.search-box { border-radius: 8px; background: #fff; border-color: rgba(0,0,0,.12); font-size: 14px; }
.search-box:focus { border-color: #0075de; box-shadow: 0 0 0 2px rgba(0,117,222,.15); }

/* ===== 洞察页组件：文档单栏内的白卡小节 ===== */
.fw-wall { grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 12px; }
.fw-card { border-radius: 8px; background: #fff; border: 1px solid rgba(0,0,0,.08); box-shadow: none; }
.fw-card:hover { border-color: rgba(0,117,222,.4); transform: none; }
.bp-track { background: #efedeb; }
.bp-fill { background: #0075de; }
.bp-thumb { box-shadow: 0 0 0 3px #e6f3fe; }
.red-item { background: #fdf1ef; border-radius: 0 8px 8px 0; }
.gap-item { border-radius: 0 8px 8px 0; }
.hm-cell { border-radius: 2px; }

/* ===== Lyon Text 编辑衬线：hero → persona 引用 → 弹窗引用 ===== */
.persona-md h1, .persona-md h2 { font-family: var(--font-display); font-size: 20px; font-weight: 700; letter-spacing: -0.011em; color: #111; margin: 20px 0 10px; }
.persona-md p, .persona-md li { font-size: 15px; color: #37352f; }
.persona-md blockquote {
  font-family: "Source Serif 4", "Noto Serif SC", "Songti SC", serif; font-style: italic;
  font-size: 16px; line-height: 1.56; color: #615d59;
  border-left: 3px solid #f6d5b8; padding: 2px 0 2px 16px; margin: 12px 0 14px;
}
.persona-md strong { color: #111; font-weight: 600; }
.mbody blockquote {
  font-family: "Source Serif 4", "Noto Serif SC", "Songti SC", serif; font-style: italic;
  font-size: 16px; line-height: 1.56; color: #615d59;
  border-left: 3px solid #f6d5b8; padding: 2px 0 2px 16px; margin: 12px 0 14px;
}

/* ===== 进度 / 标签条：平涂单色 ===== */
.tag-bar .track, .mini-plan .mp-bar, .progress-track { background: #efedeb; }
.tag-bar .fill, .progress-fill, .mini-plan .mp-fill { background: #0075de; }
.tag-bar .count, .progress-num, .plan-meta { font-family: var(--font-num); color: #757575; }
.mini-plan .mp-t { font-weight: 600; color: #111; }
.mini-plan:hover .mp-t { color: #0075de; }

/* ===== 弹窗：规范唯一允许的产品截图式阴影 ===== */
#modal-mask { background: rgba(15, 15, 15, .5); }
#modal { border-radius: 8px; padding: 32px 36px; box-shadow: 0 4px 12px rgba(0,0,0,.1); }
#modal h2 { font-size: 22px; font-weight: 700; letter-spacing: -0.011em; line-height: 1.27; color: #111; }
#modal .mmeta { color: #757575; }
#modal .mbody { border-top-color: rgba(0,0,0,.08); }
.mbody h2 { font-size: 14px !important; letter-spacing: 0 !important; font-weight: 600 !important; color: #111 !important; }
.mbody p, .mbody li { color: #37352f; font-size: 15px; }
#modal .edit-area { background: #f6f5f4; border-color: rgba(0,0,0,.1); border-radius: 8px; }

/* ===== 规划页：plan-card 白卡体系 + Kanban Task Card 任务条 ===== */
.plan-card { padding: 24px; }
.plan-head .ptitle { font-size: 18px; font-weight: 700; letter-spacing: -0.011em; color: #111; }
.plan-goal { color: #615d59; font-size: 14px; }
.task, .task:last-child {
  border: 1px solid rgba(0,0,0,.08);
  border-radius: 8px; background: #faf9f8; padding: 8px 12px; margin-bottom: 8px; font-size: 14px;
}
.task input[type="checkbox"] { border-radius: 4px; border-color: rgba(0,0,0,.3); margin-top: 2px; }
.task input[type="checkbox"]:checked { background: #0075de; border-color: #0075de; }
.plan-basis { border-top-color: rgba(0,0,0,.08); }

/* ===== 图谱 / 时间线：tl-item 并入白卡细线体系 ===== */
#graph-box { border-radius: 8px; }
.tl::before { background: rgba(0,0,0,.12); width: 1px; }
.tl-month::before { background: #0075de; box-shadow: 0 0 0 4px #e6f3fe; }
.tl-month .mname { font-family: var(--font-num); font-weight: 700; letter-spacing: -0.01em; color: #111; }
.tl-item { padding: 16px 20px; }
.tl-item .t { font-weight: 600; color: #111; }
.tl-item .d { color: #757575; }

/* ===== 状态栏 / 通知 / 拖拽遮罩 ===== */
#status-bar { background: rgba(246,245,244,.96); border-top-color: rgba(0,0,0,.08); padding-left: max(24px, calc(50% - 430px)); padding-right: max(24px, calc(50% - 430px)); }
#toast { background: #111; color: #fff; border: 0; border-radius: 8px; box-shadow: 0 4px 12px rgba(0,0,0,.18); }
#drop-mask { background: rgba(246,245,244,.92); }
#drop-mask .drop-inner { background: #fff; border-radius: 12px; }

/* ===== 移动端兜底：收回对齐内边距，签名插图缩小，stat 2×2 ===== */
@media (max-width: 960px) {
  main { padding: 0 18px 80px; }
  header { padding-left: 18px; padding-right: 18px; }
  #status-bar { padding-left: 18px; padding-right: 18px; }
  .hero { padding-top: 28px; }
  .hero .sig { width: min(320px, 100%); height: 190px; margin-bottom: 28px; }
  .stat-row { grid-template-columns: repeat(2, 1fr); }
}
